  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso; generalize A; clear - K; unfold alg; intros;
    first [ rewrite land7_mod8 in K | rewrite land3_mod4 in K | rewrite land15_mod16 in K | idtac ];
