Lemma bytes_at_nil_any : forall m m' (A : Z), bytes_at usegs m A [] -> bytes_at usegs m' A [].
Proof. intros m m' A (H0 & H1 & _). split; [exact H0|]. split; [exact H1|]. intros i Hi. cbn in Hi. lia. Qed.

Lemma StateBlock_open : forall LB m b ioc implb S ds,
  StateBlock LB m b ioc implb S ds ->
  exists p j7 j16 j4,
     In (p, b, 312) LB /\ rblock_range b 312
  /\ rw_cells usegs m b (SpcHdrCells (st_hdr S) j7) /\ spc_ok (st_hdr S) /\ spc_vptr (st_hdr S) = VP_SPCI_STATE
  /\ rw_cells usegs m (b + 32) (AnyExecCells (b + 32) ioc j16)
  /\ rw_cells usegs m (b + 88) [C8 (wz (implb + 32)); C8 (wz implb)]
  /\ PMutex m (b + 104) (st_lk S)
  /\ FlatBuf LB m (b + 144) (st_fb S) ds
  /\ PCond m (b + 192) 0
  /\ rw_cells usegs m (b + 240)
       [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
        C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)]
  /\ (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) /\ 0 <= st_nread S < 2^63 /\ 0 <= st_nread_bytes S < 2^63.
Proof.
  intros LB m b ioc implb S ds (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & PC & CO & E).
  exists p, j7, j16, j4.
  unfold SZ_SPCI_STATE, O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP, O_SPC_STORAGE in *.
  rewrite ?Z.add_0_r in CE.
  replace (b + 32 + 56) with (b + 88) in CW by lia.
  replace (b + 32 + 72) with (b + 104) in PM by lia.
  replace (b + 32 + 112) with (b + 144) in FB by lia.
  replace (b + 32 + 160) with (b + 192) in PC by lia.
  replace (b + 32 + 208) with (b + 240) in CO by lia.
  repeat (split; [assumption|]). exact E.
Qed.

Lemma StateBlock_close : forall LB m b ioc implb S ds p j7 j16 j4,
  In (p, b, 312) LB -> rblock_range b 312 ->
  rw_cells usegs m b (SpcHdrCells (st_hdr S) j7) -> spc_ok (st_hdr S) -> spc_vptr (st_hdr S) = VP_SPCI_STATE ->
  rw_cells usegs m (b + 32) (AnyExecCells (b + 32) ioc j16) ->
  rw_cells usegs m (b + 88) [C8 (wz (implb + 32)); C8 (wz implb)] ->
  PMutex m (b + 104) (st_lk S) ->
  FlatBuf LB m (b + 144) (st_fb S) ds ->
  PCond m (b + 192) 0 ->
  rw_cells usegs m (b + 240)
       [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
        C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)] ->
  (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) -> 0 <= st_nread S < 2^63 -> 0 <= st_nread_bytes S < 2^63 ->
  StateBlock LB m b ioc implb S ds.
Proof.
  intros LB m b ioc implb S ds p j7 j16 j4 IN RB CH OK EV CE CW PM FB PC CO E1 E2 E3.
  exists p, j7, j16, j4.
  unfold SZ_SPCI_STATE, O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP, O_SPC_STORAGE.
  rewrite ?Z.add_0_r.
  replace (b + 32 + 56) with (b + 88) by lia.
  replace (b + 32 + 72) with (b + 104) by lia.
  replace (b + 32 + 112) with (b + 144) by lia.
  replace (b + 32 + 160) with (b + 192) by lia.
  replace (b + 32 + 208) with (b + 240) by lia.
  repeat (split; [assumption|]). exact E3.
Qed.


