(* [comment removed for export] *)
Definition sc_segC1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb D N A E mx lo : Z) (ds : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (A, A + N); (stb + 160, stb + 168)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (stb + 144) [C8 (wz A); C8 (wz A); C8 (wz (A + N)); C8 (wz (A + N)); C8 (wz E); C8 (wz mx)]
    /\ rw_cells usegs m' A [CB (Z.to_nat N) ds]
    /\ bytes_at usegs m' D ds.

Lemma sc_segC1 : forall sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (bs stb D N A E mx ioc lo : Z) (ra s0 s1 s2 s3 s4 s4x : word) (ds junk junk40 j16 : list byte),
  rw_cells usegs m (stb + 144) [C8 (wz A); C8 (wz A); C8 (wz A); C8 (wz (A + N)); C8 (wz E); C8 (wz mx)] ->
  rw_cells usegs m A [CB (Z.to_nat N) junk] -> bytes_at usegs m D ds -> length ds = Z.to_nat N ->
  1 <= N -> 0 < A -> A + N <= hceil -> 0 <= D -> D + N <= hceil -> (D + N <= A \/ A + N <= D) ->
  0 < stb -> stb + 312 <= hceil -> (A + N <= stb \/ stb + 312 <= A) -> (D + N <= stb \/ stb + 312 <= D) ->
  0 <= E < 2^64 -> 0 <= mx < 2^64 ->
  rw_cells usegs m (bv_unsigned sp + -144) [CB 40 junk40] ->
  rw_cells usegs m (bv_unsigned sp + -104) (AnyExecCells (bv_unsigned sp + -104) ioc j16) ->
  rw_cells usegs m (bv_unsigned sp + -48) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  stk usegs m lo (bv_unsigned sp + -144) -> lo + 144 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (sc_segC1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc stb D N A E mx lo ds m)
    (MS (mkR (Z_to_bv 64 P_SC_RET2) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (Z_to_bv 64 D) (Z_to_bv 64 bs)
             (Z_to_bv 64 A) (Z_to_bv 64 N) a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 N) (Z_to_bv 64 (stb + 32)) s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SC_RET2) fc None m (seg_rom usegs)).
