(* [comment removed for export] *)
Definition sc_segC0_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (stb + 160, stb + 168)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' (stb + 144) (FlatBufCells FB_empty).

Lemma sc_segC0 : forall sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (bs stb D ioc lo : Z) (ra s0 s1 s2 s3 s4 s4x : word) (junk40 j16 : list byte),
  rw_cells usegs m (stb + 144) (FlatBufCells FB_empty) ->
  0 < stb -> stb + 312 <= hceil ->
  rw_cells usegs m (bv_unsigned sp + -144) [CB 40 junk40] ->
  rw_cells usegs m (bv_unsigned sp + -104) (AnyExecCells (bv_unsigned sp + -104) ioc j16) ->
  rw_cells usegs m (bv_unsigned sp + -48) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  stk usegs m lo (bv_unsigned sp + -144) -> lo + 144 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (sc_segC0_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc stb lo m)
    (MS (mkR (Z_to_bv 64 P_SC_RET2) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (Z_to_bv 64 D) (Z_to_bv 64 bs)
             (Z_to_bv 64 0) (Z_to_bv 64 0) a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 0) (Z_to_bv 64 (stb + 32)) s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SC_RET2) fc None m (seg_rom usegs)).
