(* [comment removed for export] *)

Definition STREAM_CTOR_STACK : Z := 144 + MAKE_IMPL_STACK.   (* [comment removed for export] *)

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition stream_ctor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (bs ioc D N allocb regb cfgb schedb slk sst ssh lo B : Z) (ds : list byte) (m : mem) (mo : Model)
      : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState)
                    (p1 : bptr) (v : Z) (p2 : bptr) (q : Z) (p3 : bptr) (stb : Z) (p4 : bptr) (va : Z) (p5 : bptr) (A : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range v NEWSZ_SSVC /\ rblock_range q SZ_SPCI_IMPL /\ rblock_range stb SZ_SPCI_STATE /\ rblock_range va 8
      /\ (1 <= N -> rblock_range A N /\ (A + N <= stb \/ stb + SZ_SPCI_STATE <= A))
      /\ hs_RHEAP H s' (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m'
      /\ rw_cells usegs m' bs (BasicStreamCells stb)
      /\ rw_cells usegs m' ioc (IoCtxCells allocb regb schedb)
      /\ AllocImpl (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' allocb
      /\ Registry (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' regb ioc v 0
      /\ ConfigSvc (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' cfgb (cfg_hdr ioc)
      /\ Scheduler (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' schedb (mkSCH (sched_hdr ioc cfgb) slk sst ssh)
      /\ StreamSvc (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' v (ssvc_hdr ioc schedb) q
      /\ ImplBlock (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' q (impl_after va stb)
      /\ StateBlock (st_LB N p5 A (mi_LB p1 v p2 q p3 stb p4 va LB)) m' stb ioc q
                    (mkST (mkSPC VP_SPCI_STATE 1 1 1) 0 (stream_fb N A) STREAM_OK 0 0) ds
      /\ bytes_at usegs m' D ds
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(bs, bs + SZ_BS); (regb, regb + NEWSZ_REG)] m m'.

  Definition stream_ctor_stmt : Prop :=
